/* GENERATED by tools/split-map.js from film-engine/src/index.html: the functions only the scenes page uses. Do not edit; edit the source or the tool. */


    function selectAllScenes(on) {
        document.querySelectorAll('.scene-select').forEach(cb => { cb.checked = on; });
        updateSceneSelection();
    }

    async function deleteSelectedScenes() {
        const ids = [...document.querySelectorAll('.scene-select:checked')].map(cb => cb.value);
        if (!ids.length) return;

        // Total the shots up front so the confirm states the real cost rather
        // than just a scene count.
        const shots = state.scenes
            .filter(sc => ids.includes(sc.id))
            .reduce((n, sc) => n + (sc.shot_count || 0), 0);
        const shotWarning = shots > 0
            ? '\n\nThis also deletes ' + shots + ' shot' + (shots === 1 ? '' : 's') + ' and their notes, versions and render history.'
            : '';

        if (!confirm('Delete ' + ids.length + ' scene' + (ids.length === 1 ? '' : 's') + '?' + shotWarning + '\n\nThis cannot be undone.')) return;

        try {
            const res = await api('/projects/' + state.currentProject.id + '/scenes/delete', {
                method: 'POST',
                body: JSON.stringify({ scene_ids: ids }),
            });
            setStatus('Deleted ' + res.deleted + ' scene(s)' + (res.shots_deleted ? ' and ' + res.shots_deleted + ' shot(s)' : ''));
            loadScenes();
        } catch (err) {
            setStatus('Could not delete scenes: ' + err.message);
        }
    }

    // FILM-124: Break down all scenes in 'written' status
    async function breakdownAllScenes() {
        if (!state.currentProject) return;
        const writtenScenes = state.scenes.filter(s => s.status === 'written');
        if (writtenScenes.length === 0) {
            setStatus('No scenes to break down');
            return;
        }

        const confirmMsg = `Break down ${writtenScenes.length} scene(s) into shots?\n\nThis will generate shot cards for all scenes in "written" status.`;
        if (!confirm(confirmMsg)) return;

        setStatus(`Breaking down ${writtenScenes.length} scene(s)...`);
        try {
            const result = await api('/projects/' + state.currentProject.id + '/breakdown', {
                method: 'POST',
                body: JSON.stringify({ all_scenes: true, auto_save: true })
            });

            if (result.parse_error) {
                setStatus('Breakdown failed: ' + result.parse_error);
                return;
            }

            const totalCards = result.total_cards || (result.saved?.reduce((sum, s) => sum + (s.saved || 0), 0)) || 0;
            setStatus(`Breakdown complete: ${totalCards} shot(s) created`);

            // Reload scenes to update status and shot counts
            loadScenes();

            // Also reload screenplay to update status icons
            if (typeof renderScreenplayEditor === 'function') {
                renderScreenplayEditor();
            }
        } catch (err) {
            setStatus('Breakdown error: ' + err.message);
        }
    }
